const fn = `() => {
  const body = document.getElementById('bodyContent');
  if (!body) return { error: 'no bodyContent' };
  const parserOut = body.querySelector('.mw-parser-output');
  if (!parserOut) return { error: 'no mw-parser-output' };
  // First direct-child paragraph (lead paragraph), skipping short-description
  const paras = Array.from(parserOut.children).filter(el => el.tagName === 'P');
  const firstPlain = paras.map(p => p.innerText.replace(/\\s+/g, ' ').trim());
  // Also grab the "leading-extract" if present
  const leadExcerpt = parserOut.querySelector('.leading-extract') || parserOut.querySelector('.mw-parser-output > .pagematrix');
  return {
    firstParagraph: paras.length ? paras[0].innerText.replace(/\\s+/g, ' ').trim() : null,
    allDirectParasCount: paras.length,
    url: window.location.href,
    title: document.querySelector('#firstHeading').innerText,
  };
}`;
const res = await tools.cdt.evaluate_script({ pageId: 2, function: fn, format: 'function', waitForStableDom: false });
console.log(JSON.stringify(res, null, 2));

